INSERT INTO dex_sources (dataset_id, source_kind, file_name, file_sha256, metadata) VALUES
('emerald-ex-1.0.4', 'stats_types', 'pokemon_emerald_ex_1.0.4_stats_types.json', 'de9584fc47d46a81faa44d7e22d64c8146ac2251832b35036e39d5109fdc0712', '{"game":"Pokémon Emerald EX","version":"1.0.4","speciesFormCount":1523,"typeIdMapping":{"0":"Normal","1":"Fighting","2":"Flying","3":"Poison","4":"Ground","5":"Rock","6":"Bug","7":"Ghost","8":"Steel","9":"Mystery","10":"Fire","11":"Water","12":"Grass","13":"Electric","14":"Psychic","15":"Ice","16":"Dragon","17":"Dark","18":"Fairy"},"notes":["Extracted directly from the supplied ROM binary.","Stats are base stats, not calculated in-battle stats.","Emerald EX 1.0.4 uses the classic Gen 3 type ID ordering with Fairy appended as ID 18.","Mono-type Pokémon store the same type in both type slots; types collapses those to one readable value.","baseStatTotal is the sum of HP, Attack, Defense, Sp. Atk, Sp. Def, and Speed."]}'),
('emerald-ex-1.0.4', 'learnsets', 'pokemon_emerald_ex_1.0.4_learnsets.json', 'a66e67e24899430cdff3bfb2e033c78526eed7bcce3bf4d2d0a00be5658b37d8', '{"game":"Pokémon Emerald EX","version":"1.0.4","sourceRom":"Pokemon Emerald Ex (1.0.4) hkcmoris.gba","sourceRomSha256":"6150445dadedc9e95cb16ffb0be1bce37e632ce2fd2777bec6201eeec8e54e57","speciesFormCount":1523,"moveCount":935,"levelUpEntryCount":23729,"notes":["Extracted directly from the supplied ROM binary.","Every learnset entry includes type, category, power, accuracy, PP, priority and description.","power=0 means no normal fixed base power; this includes status moves and moves whose damage/power is handled specially.","accuracy=0 means no normal percentage accuracy check; the move may be always-hit, non-damaging, or use special battle logic.","effectId and targetId are preserved in the top-level moves table as raw engine IDs."]}'),
('emerald-ex-1.0.4', 'evolutions', 'pokemon_emerald_ex_1.0.4_evolutions.json', '5de54982e7e819d001b699475471c8b954a17f0d172a9cdedf289d6923ac19fc', '{"game":"Pokémon Emerald EX","version":"1.0.4","sourceRom":"Pokemon Emerald Ex (1.0.4).gba","sourceRomSha256":"6150445dadedc9e95cb16ffb0be1bce37e632ce2fd2777bec6201eeec8e54e57","speciesFormSlots":1523,"normalEvolutionRules":618,"internalFormRoutingMarkers":26,"notes":["Extracted directly from the supplied ROM binary.","The ROM uses an older pokeemerald-expansion evolution-method enum.","rawParam preserves the exact 16-bit evolution parameter stored in the ROM.","internalOnly=true marks EVO_NONE-style alternate-form routing entries; these are not ordinary player-triggered evolution methods.","Map-section ID 63 resolves to New Mauville from the ROM''s own region-map table.","Specific map IDs 6923 and 6995 are preserved as raw IDs; their Moss Rock / icy-area labels are semantic hints based on the Pokémon that use them."]}'),
('emerald-ex-1.0.4', 'tm_hm_compatibility', 'pokemon_emerald_ex_1.0.4_tm_hm_compatibility.json', 'a034eaa723f321e266e815a58308aa47a09dedabea2d6b22c69fb3ea01039a88', '{"game":"Pokémon Emerald EX","version":"1.0.4","sourceRom":"Pokemon Emerald Ex (1.0.4).gba","sourceRomSha256":"6150445dadedc9e95cb16ffb0be1bce37e632ce2fd2777bec6201eeec8e54e57","speciesFormCount":1523,"tmCount":50,"hmCount":8,"machineCount":58,"compatibleSpeciesMachinePairs":32358,"notes":["Compatibility is extracted from the ROM''s per-species teachable-move tables.","Engine-level teachable-move rules are applied in addition to the raw ROM arrays.","Mew is special-cased by the engine to learn all 50 TMs and all 8 HMs in this machine set.","TM10 Hidden Power, TM21 Frustration, TM27 Return, and TM43 Secret Power use the engine''s universal-move rules.","TM-illiterate species only receive a universal TM if that move is also in their level-up learnset under the configured Gen 6+ TM-literacy behavior.","Pyukumuku is explicitly blocked by the engine from Hidden Power, Return, and Frustration.","The per-species arrays may contain move-tutor moves too; this export filters them out and includes only TM01-TM50 and HM01-HM08.","This compact file lists only compatible TMs/HMs for each species/form."],"format":"compact"}');
